INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumothorax-0-2', '2026.09.1', '{"id":"pneumothorax-0-2","unitId":"pneumothorax","version":"2026.09.1","mode":0,"difficulty":2,"ordered":true,"briefing":"A fictional adult has a right-sided pneumothorax with an established indication for drainage. Work independently, identify unsafe actions and reassess the response.","debrief":"Drainage reduces the illustrated pleural air collection. Lung expansion improves in this selected case; monitoring and follow-up remain necessary. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Inspect the affected lung","instruction":"Select the right superior lung lobe and examine the illustrated loss of expansion.","targetId":"MAL_RUL","action":3,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumothorax-0-2-0","essential":true,"weight":1,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumothorax-step-0"},{"title":"Identify the pleural boundary","instruction":"Find the right parietal pleura. Distinguish it from lung tissue.","targetId":"REC_Right_Parietal_Pleura","action":0,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumothorax-0-2-1","essential":true,"weight":1,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumothorax-0-2-0"],"narration":"pneumothorax-step-1"},{"title":"Prepare the drainage circuit","instruction":"Grasp the drain connector and place it in the drainage-unit socket.","targetId":"equipment:drain-circuit","action":4,"toolId":"connector","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumothorax-0-2-2","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumothorax-0-2-1"],"narration":"pneumothorax-step-2"},{"title":"Localize the planned site","instruction":"Bring the localization probe to the marked case-specific pleural target and hold it steady.","targetId":"REC_Right_Parietal_Pleura","action":5,"toolId":"probe","equipmentState":"ready","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumothorax-0-2-3","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumothorax-0-2-2"],"narration":"pneumothorax-step-3"},{"title":"Control the instrument trajectory","instruction":"Advance the drainage catheter through the displayed training path. Keep the tip away from protected structures.","targetId":"REC_Right_Parietal_Pleura","action":7,"toolId":"drain","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumothorax-0-2-4","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0.95,"prerequisites":["pneumothorax-0-2-3"],"narration":"pneumothorax-step-4"},{"title":"Establish controlled drainage","instruction":"With the drain aligned at the target and the circuit connected, hold the action control to open the circuit.","targetId":"REC_Right_Parietal_Pleura","action":6,"toolId":"drain","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumothorax-0-2-5","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumothorax-0-2-4"],"narration":"pneumothorax-step-5"},{"title":"Reassess the lung","instruction":"Use the assessment probe on the affected lung and compare expansion with the initial state.","targetId":"MAL_RUL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumothorax-0-2-6","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["pneumothorax-0-2-5"],"narration":"pneumothorax-step-6"}],"protectedIds":["REC_Right_IC4_Nerve","REC_Right_IC4_Artery","FMA13295"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('asthma-0-0', '2026.09.1', '{"id":"asthma-0-0","unitId":"asthma","version":"2026.09.1","mode":0,"difficulty":0,"ordered":true,"briefing":"A fictional adult has reversible airway narrowing and a prescribed inhaled treatment plan. A narrated checklist and placement cues are available during practice.","debrief":"The airway teaching view illustrates improved opening after successful delivery. Continued management and reassessment remain part of the scenario. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Inspect airway narrowing","instruction":"Select the right main bronchus to examine the enlarged airway view.","targetId":"FMA68418","action":3,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"asthma-0-0-0","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"asthma-step-0"},{"title":"Identify the delivery route","instruction":"Trace the route through the trachea before assembling the inhaler.","targetId":"FMA7394","action":0,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"asthma-0-0-1","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["asthma-0-0-0"],"narration":"asthma-step-1"},{"title":"Assemble the spacer","instruction":"Place the inhaler connector in the spacer socket.","targetId":"equipment:spacer","action":4,"toolId":"connector","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"asthma-0-0-2","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-1"],"narration":"asthma-step-2"},{"title":"Establish the mouthpiece seal","instruction":"Hold the spacer mouthpiece against the device training interface with the correct orientation.","targetId":"equipment:mouthpiece","action":5,"toolId":"spacer","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"asthma-0-0-3","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-2"],"narration":"asthma-step-3"},{"title":"Coordinate delivery","instruction":"Hold the action control while aligned at the mouthpiece during the highlighted inspiration phase.","targetId":"equipment:mouthpiece","action":6,"toolId":"inhaler","equipmentState":"inspiration","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"asthma-0-0-4","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-3"],"narration":"asthma-step-4"},{"title":"Reassess the airway","instruction":"Apply the assessment probe to the right main bronchus and compare the illustrated airway opening.","targetId":"FMA68418","action":8,"toolId":"probe","equipmentState":"ready","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"asthma-0-0-5","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["asthma-0-0-4"],"narration":"asthma-step-5"}],"protectedIds":["FMA7131"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
