INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('coronary-disease-0-0', '2026.09.1', '{"id":"coronary-disease-0-0","unitId":"coronary-disease","version":"2026.09.1","mode":0,"difficulty":0,"ordered":true,"briefing":"A fictional patient has a coronary lesion selected for balloon/stent intervention by the case treatment plan. A narrated checklist and placement cues are available during practice.","debrief":"The lesion view shows a larger treated lumen and improved illustrative flow. Ongoing coronary disease care is still required. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Inspect the coronary lesion","instruction":"Select the left coronary artery and examine the lesion teaching view.","targetId":"FMA50040","action":3,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-0","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"coronary-disease-step-0"},{"title":"Identify the coronary origin","instruction":"Select the ascending aorta to establish its relation to the coronary origin.","targetId":"FMA3736","action":0,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-1","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-0"],"narration":"coronary-disease-step-1"},{"title":"Prepare the delivery system","instruction":"Connect the catheter delivery handle to the prepared equipment socket.","targetId":"equipment:catheter-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-2","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-1"],"narration":"coronary-disease-step-2"},{"title":"Navigate the guidewire","instruction":"Move the guidewire through the ordered target route without entering protected anatomy.","targetId":"FMA50040","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-3","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0.95,"prerequisites":["coronary-disease-0-0-2"],"narration":"coronary-disease-step-3"},{"title":"Align the balloon","instruction":"Hold the balloon catheter at the lesion target with the specified orientation.","targetId":"FMA50040","action":5,"toolId":"balloon","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-4","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-3"],"narration":"coronary-disease-step-4"},{"title":"Perform the planned balloon action","instruction":"Activate the aligned balloon at the case target, observing the lesion view.","targetId":"FMA50040","action":6,"toolId":"balloon","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-5","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-4"],"narration":"coronary-disease-step-5"},{"title":"Position and deploy the stent","instruction":"Align the stent delivery tool with the treated target and activate it.","targetId":"FMA50040","action":6,"toolId":"stent","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-6","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-5"],"narration":"coronary-disease-step-6"},{"title":"Reassess the treated vessel","instruction":"Use the probe to compare the lesion and flow views with the initial condition.","targetId":"FMA50040","action":8,"toolId":"probe","equipmentState":"ready","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-0-7","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["coronary-disease-0-0-6"],"narration":"coronary-disease-step-7"}],"protectedIds":["FMA7252","FMA7253","FMA7254"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
