INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('coronary-disease-0-2', '2026.09.1', '{"id":"coronary-disease-0-2","unitId":"coronary-disease","version":"2026.09.1","mode":0,"difficulty":2,"ordered":true,"briefing":"A fictional patient has a coronary lesion selected for balloon/stent intervention by the case treatment plan. Work independently, identify unsafe actions and reassess the response.","debrief":"The lesion view shows a larger treated lumen and improved illustrative flow. Ongoing coronary disease care is still required. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Inspect the coronary lesion","instruction":"Select the left coronary artery and examine the lesion teaching view.","targetId":"FMA50040","action":3,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-0","essential":true,"weight":1,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"coronary-disease-step-0"},{"title":"Identify the coronary origin","instruction":"Select the ascending aorta to establish its relation to the coronary origin.","targetId":"FMA3736","action":0,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-1","essential":true,"weight":1,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["coronary-disease-0-2-0"],"narration":"coronary-disease-step-1"},{"title":"Prepare the delivery system","instruction":"Connect the catheter delivery handle to the prepared equipment socket.","targetId":"equipment:catheter-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-2","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["coronary-disease-0-2-1"],"narration":"coronary-disease-step-2"},{"title":"Navigate the guidewire","instruction":"Move the guidewire through the ordered target route without entering protected anatomy.","targetId":"FMA50040","action":7,"toolId":"guidewire","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-3","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0.95,"prerequisites":["coronary-disease-0-2-2"],"narration":"coronary-disease-step-3"},{"title":"Align the balloon","instruction":"Hold the balloon catheter at the lesion target with the specified orientation.","targetId":"FMA50040","action":5,"toolId":"balloon","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-4","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["coronary-disease-0-2-3"],"narration":"coronary-disease-step-4"},{"title":"Perform the planned balloon action","instruction":"Activate the aligned balloon at the case target, observing the lesion view.","targetId":"FMA50040","action":6,"toolId":"balloon","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-5","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["coronary-disease-0-2-4"],"narration":"coronary-disease-step-5"},{"title":"Position and deploy the stent","instruction":"Align the stent delivery tool with the treated target and activate it.","targetId":"FMA50040","action":6,"toolId":"stent","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-6","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["coronary-disease-0-2-5"],"narration":"coronary-disease-step-6"},{"title":"Reassess the treated vessel","instruction":"Use the probe to compare the lesion and flow views with the initial condition.","targetId":"FMA50040","action":8,"toolId":"probe","equipmentState":"ready","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"coronary-disease-0-2-7","essential":true,"weight":2,"maxDistance":0.025,"maxAngle":18,"minContactSeconds":1.2,"minPathFraction":0,"prerequisites":["coronary-disease-0-2-6"],"narration":"coronary-disease-step-7"}],"protectedIds":["FMA7252","FMA7253","FMA7254"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pneumonia-0-0', '2026.09.1', '{"id":"pneumonia-0-0","unitId":"pneumonia","version":"2026.09.1","mode":0,"difficulty":0,"ordered":true,"briefing":"A fictional adult has diagnosed bacterial pneumonia with prescribed treatment and respiratory-support orders. A narrated checklist and placement cues are available during practice.","debrief":"The timeline illustrates gradual improvement in the affected air spaces. Delivery alone is not proof of recovery; reassessment and completing the prescribed course are represented. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Inspect the affected lobe","instruction":"Select the right inferior lung lobe and inspect the inflammatory teaching view.","targetId":"MAL_RLL","action":3,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumonia-0-0-0","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pneumonia-step-0"},{"title":"Locate its airway relationship","instruction":"Identify the lower-lobe bronchial tree.","targetId":"FMA31747","action":0,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumonia-0-0-1","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pneumonia-0-0-0"],"narration":"pneumonia-step-1"},{"title":"Prepare prescribed care","instruction":"Connect the prepared administration device to its designated port.","targetId":"equipment:prescribed-care","action":4,"toolId":"connector","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumonia-0-0-2","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-1"],"narration":"pneumonia-step-2"},{"title":"Deliver the prescribed treatment","instruction":"Place the labeled treatment device in its administration dock and hold the action control.","targetId":"equipment:prescribed-care","action":6,"toolId":"medication","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumonia-0-0-3","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-2"],"narration":"pneumonia-step-3"},{"title":"Apply ordered respiratory support","instruction":"Align the respiratory-support device with the training interface and activate the prescribed setting.","targetId":"equipment:mouthpiece","action":6,"toolId":"oxygen","equipmentState":"connected","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumonia-0-0-4","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-3"],"narration":"pneumonia-step-4"},{"title":"Reassess respiratory response","instruction":"Probe the affected lung lobe and inspect the time-compressed recovery sequence.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pneumonia-0-0-5","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pneumonia-0-0-4"],"narration":"pneumonia-step-5"}],"protectedIds":["REC_Right_Phrenic_nerve"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
