INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('pleural-effusion-0-0', '2026.09.1', '{"id":"pleural-effusion-0-0","unitId":"pleural-effusion","version":"2026.09.1","mode":0,"difficulty":0,"ordered":true,"briefing":"A fictional patient has a right pleural fluid collection and an established plan for aspiration. A narrated checklist and placement cues are available during practice.","debrief":"The illustrated pleural fluid volume decreases and expansion may improve. The debrief addresses monitoring and investigation of the underlying cause. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Inspect the fluid collection","instruction":"Select the right parietal pleura and inspect the fluid outside the lung.","targetId":"REC_Right_Parietal_Pleura","action":3,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pleural-effusion-0-0-0","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"pleural-effusion-step-0"},{"title":"Identify the diaphragm boundary","instruction":"Locate the diaphragm and keep its relationship in view.","targetId":"FMA13295","action":0,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pleural-effusion-0-0-1","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-0"],"narration":"pleural-effusion-step-1"},{"title":"Prepare collection equipment","instruction":"Connect the aspiration connector to the collection-unit socket.","targetId":"equipment:aspiration","action":4,"toolId":"connector","equipmentState":"connected","explanation":"The re