ly the probe to the right inferior lobe to compare the response.","targetId":"MAL_RLL","action":8,"toolId":"probe","equipmentState":"ready","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"pleural-effusion-0-0-6","essential":true,"weight":2,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0.6,"minPathFraction":0,"prerequisites":["pleural-effusion-0-0-5"],"narration":"pleural-effusion-step-6"}],"protectedIds":["FMA13295","REC_Right_IC6_Nerve","REC_Right_IC6_Artery"]}'::jsonb) ON CONFLICT (id,version) DO UPDATE SET definition=excluded.definition;
