INSERT INTO public.thorax_learning_definitions (id, version, definition) VALUES ('aortic-stenosis-0-0', '2026.09.1', '{"id":"aortic-stenosis-0-0","unitId":"aortic-stenosis","version":"2026.09.1","mode":0,"difficulty":0,"ordered":true,"briefing":"A fictional patient has a narrowed aortic valve and has been selected for catheter-based replacement. A narrated checklist and placement cues are available during practice.","debrief":"The valve teaching view illustrates improved opening and forward flow after correct placement. Follow-up and complication monitoring remain necessary. Fictional, fixed-indication learning scenario. Responses are illustrative and time-compressed. The model does not establish clinical competence or predict a real patient outcome.","objectives":[{"title":"Inspect the stenotic valve","instruction":"Select the anterior aortic cusp and examine restricted opening.","targetId":"FMA7253","action":3,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"aortic-stenosis-0-0-0","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":[],"narration":"aortic-stenosis-step-0"},{"title":"Identify the outflow relationship","instruction":"Locate the ascending aorta and its relation to the valve.","targetId":"FMA3736","action":0,"toolId":"","equipmentState":"","explanation":"The recorded action completes this step. Reassess the anatomy before continuing.","id":"aortic-stenosis-0-0-1","essential":true,"weight":1,"maxDistance":0.06,"maxAngle":40,"minContactSeconds":0,"minPathFraction":0,"prerequisites":["aortic-stenosis-0-0-0"],"narration":"aortic-stenosis-step-1"},{"title":"Prepare the valve system","instruction":"Connect the valve delivery system to its prepared socket.","targetId":"equipment:valve-system","action":4,"toolId":"connector","equipmentState":"connected","explanation":"The recorded action completes this step. R